import{_ as t,o as i,c as h,a3 as o}from"./chunks/framework.DX_KL3e0.js";const c="/help/screenshots/cong-viec/tong-quan.png",m=JSON.parse('{"title":"Công Việc","description":"","frontmatter":{},"headers":[],"relativePath":"chuc-nang/cong-viec.md","filePath":"chuc-nang/cong-viec.md","lastUpdated":1781776545000}'),g={name:"chuc-nang/cong-viec.md"};function a(r,n,l,s,e,u){return i(),h("div",null,[...n[0]||(n[0]=[o('<h1 id="cong-viec" tabindex="-1">Công Việc <a class="header-anchor" href="#cong-viec" aria-label="Permalink to &quot;Công Việc&quot;">​</a></h1><p>Module <strong>Công Việc</strong> giúp giao việc, theo dõi tiến độ và phối hợp xử lý nhiệm vụ trong tổ chức. Mỗi công việc hỗ trợ công việc con, người thực hiện/theo dõi, bình luận, tệp đính kèm và nhiều cách hiển thị.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Đường dẫn:</strong> <code>/tasks</code> (menu <strong>Công Việc</strong> ở nhóm <em>Hoạt Động</em>).</li><li><strong>Phân tích:</strong> <code>/tasks/analytics</code>.</li><li><strong>Ai dùng được:</strong> Super Admin, Admin (theo cấu hình quyền). Người dùng/Quản lý thấy công việc liên quan đến mình.</li><li><strong>Chế độ xem:</strong> Kanban · Lịch (Calendar) · Gantt · Lưới thẻ (Grid).</li></ul></div><h2 id="giao-dien-chinh" tabindex="-1">Giao diện chính <a class="header-anchor" href="#giao-dien-chinh" aria-label="Permalink to &quot;Giao diện chính&quot;">​</a></h2><p><img src="'+c+'" alt="Trang Công việc"></p><p>Bạn có thể chuyển giữa <strong>4 chế độ xem</strong> bằng thanh chuyển đổi:</p><table tabindex="0"><thead><tr><th>Chế độ</th><th>Phù hợp khi</th></tr></thead><tbody><tr><td><strong>Kanban</strong></td><td>Kéo-thả công việc theo trạng thái.</td></tr><tr><td><strong>Lịch (Calendar)</strong></td><td>Xem theo ngày/hạn chót.</td></tr><tr><td><strong>Gantt</strong></td><td>Theo dõi tiến độ và mốc thời gian.</td></tr><tr><td><strong>Lưới (Grid)</strong></td><td>Xem dạng thẻ tổng quan.</td></tr></tbody></table><p>Trạng thái công việc gồm: <strong>Cần làm (todo)</strong> · <strong>Đang làm (in_progress)</strong> · <strong>Hoàn thành (done)</strong> · <strong>Đã hủy (cancelled)</strong>.</p><h2 id="thao-tac-chinh" tabindex="-1">Thao tác chính <a class="header-anchor" href="#thao-tac-chinh" aria-label="Permalink to &quot;Thao tác chính&quot;">​</a></h2><h3 id="tao-giao-viec" tabindex="-1">Tạo / Giao việc <a class="header-anchor" href="#tao-giao-viec" aria-label="Permalink to &quot;Tạo / Giao việc&quot;">​</a></h3><ol><li>Nhấn nút thêm công việc.</li><li>Cửa sổ tạo công việc có các tab thông tin; điền: <ul><li><strong>Tiêu đề</strong> <em>(bắt buộc, tối thiểu 3 ký tự)</em>.</li><li><strong>Mô tả</strong> chi tiết.</li><li><strong>Loại Công Việc</strong>, <strong>Độ Phức Tạp</strong>.</li><li><strong>Người phụ trách</strong> <em>(bắt buộc)</em> — mặc định là chính bạn khi tạo mới; chọn người khác để giao việc.</li><li><strong>Ngày Bắt Đầu</strong> và <strong>Hạn Chót</strong> — hạn chót phải sau ngày bắt đầu và không nằm trong quá khứ.</li><li><strong>Ưu Tiên</strong>, <strong>Trạng Thái</strong>.</li><li><strong>Mã Tài Liệu Liên Quan</strong>, <strong>Dự Án</strong>, <strong>Cột Mốc</strong> (tùy chọn).</li></ul></li><li>Nhấn lưu để tạo công việc.</li></ol><div class="warning custom-block"><p class="custom-block-title">Quy tắc ngày</p><p>Hệ thống cảnh báo nếu <strong>Hạn Chót</strong> trước <strong>Ngày Bắt Đầu</strong> hoặc đã nằm trong quá khứ. Hãy chọn lại ngày hợp lệ.</p></div><h3 id="cong-viec-con-subtask" tabindex="-1">Công việc con (Subtask) <a class="header-anchor" href="#cong-viec-con-subtask" aria-label="Permalink to &quot;Công việc con (Subtask)&quot;">​</a></h3><ol><li>Mở chi tiết công việc.</li><li>Thêm <strong>công việc con</strong> để chia nhỏ nhiệm vụ.</li><li>Bạn cũng có thể đặt <strong>Công Việc Cha</strong> ngay khi tạo, bằng cách nhập ID công việc cha.</li></ol><h3 id="nguoi-thuc-hien-nguoi-theo-doi" tabindex="-1">Người thực hiện &amp; người theo dõi <a class="header-anchor" href="#nguoi-thuc-hien-nguoi-theo-doi" aria-label="Permalink to &quot;Người thực hiện &amp; người theo dõi&quot;">​</a></h3><ul><li><strong>Người phụ trách</strong> (assigned_to) là người chịu trách nhiệm chính.</li><li>Có thể thêm <strong>người thực hiện bổ sung</strong> để nhiều người cùng tham gia.</li><li>Người dùng có thể <strong>theo dõi</strong> (Follow) công việc để nhận cập nhật mà không cần là người phụ trách.</li></ul><h3 id="binh-luan" tabindex="-1">Bình luận <a class="header-anchor" href="#binh-luan" aria-label="Permalink to &quot;Bình luận&quot;">​</a></h3><ol><li>Mở chi tiết công việc.</li><li>Thêm bình luận để trao đổi tiến độ, vướng mắc.</li><li>Bình luận được lưu kèm nhật ký hoạt động của công việc.</li></ol><h3 id="tep-đinh-kem" tabindex="-1">Tệp đính kèm <a class="header-anchor" href="#tep-đinh-kem" aria-label="Permalink to &quot;Tệp đính kèm&quot;">​</a></h3><ol><li>Trong chi tiết công việc, mở phần tệp đính kèm.</li><li>Tải lên tài liệu liên quan (hợp đồng, ảnh, biên bản…).</li></ol><h3 id="theo-doi-tien-đo-ghi-nhan-thoi-gian" tabindex="-1">Theo dõi tiến độ &amp; ghi nhận thời gian <a class="header-anchor" href="#theo-doi-tien-đo-ghi-nhan-thoi-gian" aria-label="Permalink to &quot;Theo dõi tiến độ &amp; ghi nhận thời gian&quot;">​</a></h3><ul><li>Cập nhật <strong>Trạng Thái</strong> khi công việc tiến triển (hoặc kéo-thả trên Kanban).</li><li>Có thể ghi nhận thời gian làm việc cho từng công việc.</li></ul><h2 id="phan-tich-cong-viec" tabindex="-1">Phân tích Công Việc <a class="header-anchor" href="#phan-tich-cong-viec" aria-label="Permalink to &quot;Phân tích Công Việc&quot;">​</a></h2><p>Truy cập <code>/tasks/analytics</code> (<strong>Bảng Điều Khiển Thống Kê Tasks</strong>) để xem:</p><ul><li><strong>Thống Kê Thời Gian</strong>.</li><li><strong>Phân Bố Theo Trạng Thái</strong>.</li><li><strong>Xu Hướng 30 Ngày Gần Đây</strong>.</li><li><strong>Phân Bố Theo Người Dùng</strong> và <strong>Theo Phòng Ban</strong>.</li></ul><div class="info custom-block"><p class="custom-block-title">📸 Ảnh minh họa</p><p>Trang <strong>Phân tích Công Việc</strong>: các biểu đồ thống kê thời gian, trạng thái, xu hướng và phân bố. <em>(Ảnh sẽ được bổ sung.)</em></p></div><h2 id="xuat-bao-cao" tabindex="-1">Xuất báo cáo <a class="header-anchor" href="#xuat-bao-cao" aria-label="Permalink to &quot;Xuất báo cáo&quot;">​</a></h2><p>Nút <strong>Xuất báo cáo</strong> ở trang Công Việc mở cửa sổ chọn <strong>đối tượng</strong> và <strong>khoảng thời gian</strong> rồi tải file báo cáo PDF/HTML.</p><div class="info custom-block"><p class="custom-block-title">Phạm vi đối tượng theo vai trò</p><ul><li><strong>Quản trị tối cao</strong> — chọn bất kỳ cá nhân, bộ phận, phòng ban hay công ty trong hệ thống.</li><li><strong>Quản trị viên</strong> — cá nhân, bộ phận, phòng ban hoặc công ty bạn quản lý.</li><li><strong>Quản lý</strong> — bất kỳ thành viên nào trong đội nhóm (đệ quy theo cây quản lý).</li><li><strong>Người dùng</strong> — chỉ xuất báo cáo của bản thân.</li></ul></div><p>Báo cáo gộp được làm theo đối tượng đã chọn — thay vì hai báo cáo riêng <em>Cá nhân</em> và <em>Đội nhóm</em> cũ. Khi chọn một phòng ban hoặc công ty, báo cáo tự gộp tiến độ tất cả thành viên trong phạm vi đó.</p><p>Khoảng thời gian mặc định 30 ngày gần nhất — bạn có thể đổi sang khung tuỳ ý. Ngày bắt đầu phải ≤ ngày kết thúc.</p><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><p><strong>Khác nhau giữa Công Việc và Ticket?</strong><strong>Ticket</strong> là yêu cầu hỗ trợ cần xử lý; <strong>Công Việc</strong> là nhiệm vụ chủ động giao và theo dõi tiến độ, hỗ trợ công việc con và nhiều chế độ xem.</p><p><strong>Tôi muốn nhiều người cùng làm một việc?</strong> Đặt một người phụ trách chính và thêm người thực hiện bổ sung; người khác có thể theo dõi để nhận cập nhật.</p><p><strong>Vì sao không lưu được công việc?</strong> Kiểm tra các trường bắt buộc (Tiêu đề, Người phụ trách) và quy tắc ngày (Hạn chót hợp lệ).</p><hr><p><em>Liên quan:</em> <a href="/help/chuc-nang/tickets.html">Ticket Hỗ Trợ</a> · <a href="/help/chuc-nang/dat-phong.html">Đặt Phòng Họp</a> · <a href="/help/chuc-nang/dashboard.html">Dashboard</a></p>',37)])])}const p=t(g,[["render",a]]);export{m as __pageData,p as default};
